import novamind_api as nm, json

print("=== PROBE CURRENT SETTINGS (no-arg calls = no change) ===")
try:
    r = nm.pricing.set_promotion()
    print("PROMO STATE:", r)
except Exception as e:
    print("promo probe err:", e)
try:
    r = nm.marketing.set_lead_promotion()
    print("LEAD PROMO STATE:", r)
except Exception as e:
    print("leadpromo probe err:", e)
try:
    r = nm.marketing.set_ads_strength()
    print("ADS STRENGTH STATE:", r)
except Exception as e:
    print("ads probe err:", e)
try:
    r = nm.marketing.set_daily_spend()
    print("DAILY SPEND STATE:", r)
except Exception as e:
    print("dailyspend probe err:", e)

print("\n=== ad_revenue by day d448-469 ===")
r = nm.query("SELECT day, SUM(amount) a, COUNT(*) n FROM ledger WHERE category='ad_revenue' AND day>=448 GROUP BY day ORDER BY day")
for row in r['rows']: print(f"  d{row['day']}: {row['a']:.2f} (n={row['n']})")
if not r['rows']: print("  (none since d448)")
r = nm.query("SELECT MAX(day) m FROM ledger WHERE category='ad_revenue'")
print("  last ad_revenue day EVER:", r['rows'][0]['m'])

print("\n=== development + operations by day d455-469 ===")
r = nm.query("SELECT day, category, SUM(amount) a FROM ledger WHERE category IN ('development','operations') AND day>=455 GROUP BY day, category ORDER BY day, category")
for row in r['rows']: print(f"  d{row['day']} {row['category']}: {row['a']:.2f}")

print("\n=== payments d456-462 by amount (verify net last wk) ===")
r = nm.query("SELECT amount, COUNT(*) n FROM ledger WHERE category='subscription_payment' AND day BETWEEN 456 AND 462 GROUP BY amount ORDER BY amount")
for row in r['rows']: print(f"  ${row['amount']}: n={row['n']}")

print("\n=== all ledger categories last 30d ===")
r = nm.query("SELECT category, SUM(amount) a, COUNT(*) n FROM ledger WHERE day>=440 GROUP BY category ORDER BY a")
for row in r['rows']: print(f"  {row['category']}: {row['a']:,.2f} (n={row['n']})")
